// ¿Qué hay «de fábrica» en el lugar donde corre este código?
// Ni console, ni setTimeout, ni fetch son parte del lenguaje JavaScript: los pone el runtime.
const nombres = ["Array", "JSON", "Promise", "console", "setTimeout", "fetch", "process", "Buffer", "window", "document", "WorkerGlobalScope"];
for (const n of nombres) {
  console.log(n.padEnd(18), typeof globalThis[n]);
}

// BIBLIOTECA: vos la llamás, ella hace su trabajo y te devuelve el control.
const biblioteca = {
  total(pedidos) { return pedidos.reduce((suma, p) => suma + p.kilos, 0); },
};

// FRAMEWORK: vos le dejás tus funciones y él decide cuándo llamarlas.
function miniFramework(config) {
  const pedidos = [{ kilos: 120 }, { kilos: 80 }, { kilos: 40 }];
  console.log("[framework] arranca");
  config.alIniciar?.();                       // el framework llama a tu código
  for (const p of pedidos) {
    console.log(`[framework] llegó un pedido de ${p.kilos} kg`);
    config.alLlegarPedido(p);                 // y otra vez, cada vez que él lo decide
  }
  console.log("[framework] termina");
  config.alTerminar?.();
}

// 1) Con la biblioteca, el hilo de control es tuyo:
console.log("--- Biblioteca ---");
console.log("tu código llama a total():", biblioteca.total([{ kilos: 120 }, { kilos: 80 }, { kilos: 40 }]), "kg");

// 2) Con el framework, escribís piezas y el hilo de control es suyo:
console.log("--- Framework ---");
let acumulado = 0;
miniFramework({
  alIniciar() { console.log("  [tu código] preparo el camión"); },
  alLlegarPedido(p) { acumulado += p.kilos; console.log(`  [tu código] cargo ${p.kilos} kg, llevo ${acumulado}`); },
  alTerminar() { console.log("  [tu código] cierro la puerta con", acumulado, "kg"); },
});

// El árbol de `npm ls --all` de axios, como un grafo: cada paquete → los que necesita directamente.
const necesita = {
  "axios": ["follow-redirects", "form-data", "https-proxy-agent", "proxy-from-env"],
  "form-data": ["asynckit", "combined-stream", "es-set-tostringtag", "hasown", "mime-types"],
  "combined-stream": ["delayed-stream"],
  "es-set-tostringtag": ["es-errors", "get-intrinsic", "has-tostringtag", "hasown"],
  "get-intrinsic": ["call-bind-apply-helpers", "es-define-property", "es-errors", "es-object-atoms",
                    "function-bind", "get-proto", "gopd", "has-symbols", "hasown", "math-intrinsics"],
  "call-bind-apply-helpers": ["es-errors", "function-bind"],
  "es-object-atoms": ["es-errors"],
  "get-proto": ["dunder-proto", "es-object-atoms"],
  "dunder-proto": ["call-bind-apply-helpers", "es-errors", "gopd"],
  "has-tostringtag": ["has-symbols"],
  "hasown": ["function-bind"],
  "mime-types": ["mime-db"],
  "https-proxy-agent": ["agent-base", "debug"],
  "agent-base": ["debug"],
  "debug": ["ms"],
};

// Todo lo que cuelga de un paquete, sin contarlo dos veces (recorrido en profundidad con un conjunto de visitados).
function arrastra(paquete) {
  const vistos = new Set();
  const visitar = (p) => {
    for (const hijo of necesita[p] ?? []) {
      if (!vistos.has(hijo)) { vistos.add(hijo); visitar(hijo); }
    }
  };
  visitar(paquete);
  return vistos;
}

// El camino más corto desde la raíz hasta un paquete (lo que responde `npm explain`), con búsqueda a lo ancho.
function porQue(raiz, destino) {
  const cola = [[raiz]];
  const vistos = new Set([raiz]);
  while (cola.length) {
    const camino = cola.shift();
    const ultimo = camino[camino.length - 1];
    if (ultimo === destino) return camino;
    for (const hijo of necesita[ultimo] ?? []) {
      if (!vistos.has(hijo)) { vistos.add(hijo); cola.push([...camino, hijo]); }
    }
  }
  return null;
}

console.log("axios arrastra", arrastra("axios").size, "paquetes distintos");
console.log("form-data arrastra", arrastra("form-data").size);
console.log("¿por qué está ms?  ", porQue("axios", "ms").join(" → "));
console.log("¿por qué está es-errors? ", porQue("axios", "es-errors").join(" → "));

// Una versión mía (no es el código original) de lo que hacía left-pad: rellenar a la izquierda hasta un largo.
function leftPad(texto, largo, relleno = " ") {
  let salida = String(texto);
  while (salida.length < largo) salida = relleno + salida;
  return salida;
}

console.log(leftPad(7, 3, "0"));                  // 007
console.log("7".padStart(3, "0"));                // 007: hoy lo trae el lenguaje
console.log(leftPad(42, 5) === "42".padStart(5)); // true
console.log(leftPad("Sendero", 4));               // no recorta: Sendero
